    "help.intro": "पहले भाषा चुनें, फिर पैनल की सेटिंग करें। OBS URL कॉपी करने से पहले सहेजें।",
    "help.languageHelp": "सभी 31 भाषाएँ इंटरफ़ेस, तारीख, समय और मौसम का विवरण अनुवाद करती हैं।",
    "help.fontInstall": "OBS चलाने वाले कंप्यूटर पर फ़ॉन्ट इंस्टॉल करें। ब्राउज़र और OBS दोबारा शुरू करके सूची रीफ़्रेश करें।",
    "help.fontPermission": "रीफ़्रेश दबाएँ और Chrome या Edge के पूछने पर फ़ॉन्ट की अनुमति दें।",
    "help.fontFallback": "OBS URL इस्तेमाल करने वाले कंप्यूटर पर चुना फ़ॉन्ट होना चाहिए। नहीं होने पर वैकल्पिक फ़ॉन्ट इस्तेमाल होगा।",
    "help.fontEmpty": "Windows फ़ॉन्ट लोड करने के लिए इंस्टॉल किए फ़ॉन्ट रीफ़्रेश करें दबाएँ।",
    "help.fontNoMatch": "खोज से मेल खाने वाला कोई इंस्टॉल किया फ़ॉन्ट नहीं मिला।",
    "help.itemColorHelp": "हर आइटम का अपना रंग हो सकता है। रंग न चुनने पर पंक्ति का रंग इस्तेमाल होता है।",
    "help.dateHelp": "M, MM, MMM, MMMM, D, DD, ddd, dddd, YY या YYYY इस्तेमाल करें। विभाजक और खाली जगह अपनी पसंद से रखें।",
    "help.lineHelp": "हर पंक्ति का आकार, मोटाई, रंग, अपारदर्शिता, संरेखण, अक्षरों का रूप और दूरी बदलें।",
    "help.obsStep1": "सेटिंग चुनकर सेटिंग सहेजें दबाएँ।",
    "help.obsStep2": "OBS URL कॉपी करें दबाएँ।",
